inline BOOL setText(HWND h,LPCWSTR value){return ::SetWindowTextW(h,translate(value?value:L"").c_str());}
inline BOOL setDlgText(HWND h,int id,LPCWSTR value){return ::SetDlgItemTextW(h,id,translate(value?value:L"").c_str());}
inline LRESULT send(HWND h,UINT m,WPARAM w,LPARAM l){if((m==CB_ADDSTRING||m==LB_ADDSTRING)&&l){auto value=translate(reinterpret_cast<LPCWSTR>(l));return ::SendMessageW(h,m,w,reinterpret_cast<LPARAM>(value.c_str()));}return ::SendMessageW(h,m,w,l);}
inline int message(HWND h,LPCWSTR text,LPCWSTR title,UINT flags){return ::MessageBoxW(h,translate(text).c_str(),translate(title).c_str(),flags);}
